message.content:
{
  "hypotheses": [
    {
      "id": "H4",
      "mechanism": "Posture parameters (hip_bias, pitch_ref, stance_knee, start_lean) are not adapted to the heavier body, causing excessive forward lean and pitch drift that leads to forward falls.",
      "evidence": [
        "baseline.pitch_mean_rad",
        "baseline.pitch_drift_radps",
        "baseline.pitch_at_end_rad",
        "creature.features.mass_total",
        "creature.reference.features.mass_total"
      ],
      "competing": [
        "Forward lean may be a consequence of foot placement or stride issues rather than posture parameters."
      ]
    },
    {
      "id": "H5",
      "mechanism": "Stride amplitudes (hip_amp, knee_amp) are too small, resulting in extremely short step length (0.015 leg lengths) and inability to place the foot ahead of the torso.",
      "evidence": [
        "baseline.step_length_over_leg",
        "baseline.froude",
        "baseline.touchdown_foot_ahead_over_leg_mean",
        "baseline.capture_margin_over_leg_mean"
      ],
      "competing": [
        "Small steps may be forced by high controller frequency or torque limits rather than amplitude parameters."
      ]
    },
    {
      "id": "H6",
      "mechanism": "Body parameters (long legs, high leg density, low torque authority) create a fundamental mismatch; dynamic similarity transfer was insufficient and joint re-optimization of body and controller is needed.",
      "evidence": [
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio",
        "creature.features.mass_total",
        "creature.reference.features.mass_total",
        "creature.features.L",
        "creature.reference.features.L",
        "probes.similarity.delta_walking",
        "probes.similarity.delta_mean_fitness"
      ],
      "competing": [
        "Controller re-optimization in timing, posture, stride, and feedback may compensate without body changes."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "opt_posture",
      "hypothesis": "H4",
      "expect": "improves"
    },
    {
      "probe_id": "opt_stride",
      "hypothesis": "H5",
      "expect": "improves"
    },
    {
      "probe_id": "legs_x0_8",
      "hypothesis": "H6",
      "expect": "improves"
    }
  ]
}

